def solve(s):
    """
    Returns a dictionary with characters from string 's' as keys and their counts as values,
    excluding spaces.

    Parameters:
        s (str): The input string to analyze.

    Returns:
        dict: A dictionary where keys are unique characters from 's' and values are their respective counts.
    """
    char_count = {}
    for char in s.replace(" ", ""):
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

# Example usage:
print(solve("hello world"))  # Output: {'h': 1, 'e': 1, 'l': 3, 'o': 2, 'w': 1, 'r': 1, 'd': 1}
